function cellAt(x,z){return game.grid.find(c=>c.x===x&&c.z===z)}
function terrainCost(k,slow=game.slow){return game.map.legacy.some(n=>key(...n)===k)||slow.has(k)?1/.65:1}
function route(start,blocked=game.blocked,slow=game.slow){let m=game.map,open=[{k:key(...start),d:0}],ds=new Map([[key(...start),0]]),prev=new Map(),end=null;while(open.length){open.sort((a,b)=>a.d-b.d);let cur=open.shift();if(cur.d!==ds.get(cur.k))continue;if(m.exits.some(e=>key(...e)===cur.k)){end=cur.k;break}let [x,z]=cur.k.split(',').map(Number);for(let [dx,dz] of [[0,1],[1,0],[-1,0],[0,-1]]){let nk=key(x+dx,z+dz);if(!game.roads.has(nk)||blocked.has(nk))continue;let nd=cur.d+terrainCost(nk,slow);if(nd<(ds.get(nk)??Infinity)){ds.set(nk,nd);prev.set(nk,cur.k);open.push({k:nk,d:nd})}}}if(!end)return null;let out=[];while(end){out.unshift(end.split(',').map(Number));end=prev.get(end)}return out}
function routeTo(start,goal){let startKey=key(...start),goalKey=key(...goal),open=[{k:startKey,d:0}],ds=new Map([[startKey,0]]),prev=new Map();while(open.length){open.sort((a,b)=>a.d-b.d);let cur=open.shift();if(cur.d!==ds.get(cur.k))continue;if(cur.k===goalKey){let out=[],k=goalKey;while(k){out.unshift(k.split(',').map(Number));k=prev.get(k)}return out}let [x,z]=cur.k.split(',').map(Number);for(let [dx,dz] of [[0,1],[1,0],[-1,0],[0,-1]]){let nk=key(x+dx,z+dz);if(!game.roads.has(nk)||game.blocked.has(nk))continue;let nd=cur.d+terrainCost(nk);if(nd<(ds.get(nk)??Infinity)){ds.set(nk,nd);prev.set(nk,cur.k);open.push({k:nk,d:nd})}}}return null}
function siegeRoute(e){let current=pos(...e.cell),targets=game.towers.filter(t=>(e.type==='flood'||e.type==='boss')?(t.cell.node||t.type==='honey'):t.type==='honey');targets.sort((a,b)=>(a.type==='honey'?-5:0)+dist(current,a.group.position)-(b.type==='honey'?-5:0)-dist(current,b.group.position));for(let t of targets){if(dist(current,t.group.position)>3.7*unit)continue;let candidates=[];for(let [dx,dz] of [[0,1],[1,0],[-1,0],[0,-1]]){let x=t.cell.x+dx,z=t.cell.z+dz;if(game.roads.has(key(x,z))&&!game.blocked.has(key(x,z))){let r=routeTo(e.cell,[x,z]);if(r)candidates.push(r)}}candidates.sort((a,b)=>routeCost(a)-routeCost(b));if(candidates[0]&&candidates[0].length>1)return candidates[0]}return null}
function routesFor(blocked=game.blocked,slow=game.slow){return game.map.entries.map(e=>route(e,blocked,slow))}
function blockProblem(k){
  let b=new Set(game.blocked);b.add(k);
  let rs=routesFor(b),missing=rs.map((r,i)=>r?null:'ABC'[i]).filter(Boolean);
  if(missing.length)return '入口 '+missing.join('、')+' 将失去通往中枢的路线';
  for(let e of game.enemies){
    if(e.type==='fly')continue;
    let c=e.to||e.cell;
    if(c&&(key(...c)===k||!route(c,b)))return '坐标 '+c[0]+':'+c[1]+' 的 '+(e.type==='boss'?['万傀','蜃楼','蛰影'][game.index]:ENEMIES[e.type].name)+' 将无路可走';
  }
  return '';
}
