// Reverse weighted search caches distance-to-exit once per topology change.
function buildDistanceField(){
  let distances=new Map(),open=[];
  for(let exit of game.map.exits){let k=key(...exit);if(!game.blocked.has(k)){distances.set(k,0);open.push({k,d:0})}}
  while(open.length){
    open.sort((a,b)=>a.d-b.d);let cur=open.shift();if(cur.d!==distances.get(cur.k))continue;
    let [x,z]=cur.k.split(',').map(Number),step=terrainCost(cur.k);
    for(let [dx,dz] of [[0,1],[1,0],[-1,0],[0,-1]]){
      let previous=key(x+dx,z+dz);if(!game.roads.has(previous)||game.blocked.has(previous))continue;
      let next=cur.d+step;if(next<(distances.get(previous)??Infinity)){distances.set(previous,next);open.push({k:previous,d:next})}
    }
  }
  return distances;
}
