  let ctx=canvas.getContext('2d');ctx.font='bold 34px Microsoft YaHei UI, sans-serif';ctx.textAlign='center';ctx.lineWidth=5;ctx.strokeStyle='#061419';ctx.fillStyle=color;
  ctx.strokeText(value,80,43);ctx.fillText(value,80,43);
  let sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:new THREE.CanvasTexture(canvas),transparent:true,depthTest:false}));
  sprite.position.copy(t.group.position).add(new THREE.Vector3(0,1.55,0));sprite.scale.set(1,.4,1);game.effectGroup.add(sprite);
  game.effects.push({mesh:sprite,t:.8,popup:true});
