function piercingTarget(t,primary,targets){let o=t.group.position,p=primary.group.position,dx=p.x-o.x,dz=p.z-o.z,length=Math.hypot(dx,dz);if(length<.01)return null;return targets.filter(e=>e!==primary&&game.enemies.includes(e)).map(e=>{let x=e.group.position.x-o.x,z=e.group.position.z-o.z;return {e,along:(x*dx+z*dz)/length,across:Math.abs(x*dz-z*dx)/length}}).filter(v=>v.along>length+.08&&v.along<=TOWERS[t.type].range*unit&&v.across<.36*unit).sort((a,b)=>a.along-b.along)[0]?.e||null}
