function damageEnemy(e,amount){e.hitPulse=.22;if(e.shield>0){let absorbed=Math.min(e.shield,amount);e.shield-=absorbed;amount-=absorbed}e.hp-=amount*(1-e.armor);e.hpbar.scale.x=Math.max(0,e.hp/e.maxhp);if(e.hp<=0){shatter(e.group.position,e.type==='boss'?0xffad76:0xff796e,e.type==='boss');clearEnemyVisuals(e);if(e.type==='trojan'&&!e.revealed){for(let t of [...game.towers])if(dist(t.group.position,e.group.position)<1.5*unit){effect(e.group.position,t.group.position,0xff7c69);hurtTower(t,18)}}if(selected===e){selected=null;renderInspect()}game.kills++;game.cpu+=8;if(['flood','shield','boss'].includes(e.type))game.intel+=1;world.remove(e.group);disposeTree(e.group);game.enemies.splice(game.enemies.indexOf(e),1);sfx('kill')}}
