function removeTower(t,refund=true){if(!game.towers.includes(t))return;if(placing?.type==='remove'&&placing.tower===t){cancelPlace();if(!refund)notify('设备已失效 / 撤下预览关闭')}world.remove(t.group);disposeTree(t.group);game.towers.splice(game.towers.indexOf(t),1);if(!refund&&!t.temporary){game.stats.lost++;shatter(t.group.position,0x9df5d7);sfx('destroy')}if(refund&&!t.temporary)game.cpu+=Math.floor(TOWERS[t.type].cost*.45);if(t.cell.node){game.blocked.delete(t.cell.k);t.cell.ring.material=mats.green;game.cool.set(t.cell.k,game.time+8);routeTransition(t.cell,0x9df5d7);updateRoutes();log('节点旁路直通，路由已重新收敛。')}if(selected===t)selected=null;renderInspect()}
function wavePlan(wave){
  let count=game.map.entries.length, final=wave===game.map.waves;
  let surge=(game.index===1&&wave===10)||(game.index===2&&wave===11);
  let unlocked=['worm'];if(wave>=2)unlocked.push('trojan');if(wave>=3)unlocked.push('flood');if(wave>=5)unlocked.push('ransom');if(wave>=7)unlocked.push('fly');if(wave>=9)unlocked.push('shield');
  let events=[], perEntry=Array.from({length:count},()=>({count:0,types:new Set()}));
  for(let entry=0;entry<count;entry++){
    let amount=(surge?8:Math.min(6,2+Math.floor((wave+1)/3)))+(entry===wave%count?1:0);
    for(let j=0;j<amount;j++){
      let type=wave===1?'worm':unlocked[(j+entry+wave)%unlocked.length];
      if(surge&&j%3===0)type='flood';
      let time=surge?j*.72+entry*.08:j*1.35+entry*.36;
      events.push({time,type,entry});perEntry[entry].count++;perEntry[entry].types.add(type);
    }
  }
  if(final){let time=Math.max(...events.map(e=>e.time))+2;events.push({time,type:'boss',entry:0});perEntry[0].count++;perEntry[0].types.add('boss')}
  events.sort((a,b)=>a.time-b.time||a.entry-b.entry);
  return {events,perEntry,surge};
}
function startWave(){
  if(!game||game.running||game.finished)return;
  if(game.wave>=game.map.waves){notify('最终波次已开始，请先清除场上威胁');return}
  game.wave++;game.running=true;let plan=wavePlan(game.wave);game.spawn=plan.events;game.currentPlan=plan;game.spawnTime=0;
  log(`第 ${game.wave} 波${plan.surge?' / 洪峰告警':''}，检测到 ${plan.events.length} 个威胁。`);
  notify(plan.surge?'洪峰告警 / 三个入口同时受袭':'入侵告警 / 第 '+game.wave+' 波');renderUI();sfx(plan.surge?'warning':'wave')
}
