function occupiedTile(e){
  return key(Math.round(e.group.position.x/unit+5),Math.round(e.group.position.z/unit+4));
}
function slowArea(cell){return game.grid.filter(tile=>tile.road&&Math.abs(tile.x-cell.x)+Math.abs(tile.z-cell.z)<=1)}
function previewSlowArea(cell){
  for(let tile of slowArea(cell)){
    let p=pos(tile.x,tile.z);
    let surface=mesh(new THREE.PlaneGeometry(.98,.98),new THREE.MeshBasicMaterial({color:0xe7c578,transparent:true,opacity:.25,side:THREE.DoubleSide,depthWrite:false}),p.x,.27,p.z,game.previewGroup);
    surface.rotation.x=-Math.PI/2;
    let border=mesh(new THREE.RingGeometry(.39,.44,4),new THREE.MeshBasicMaterial({color:0xffdfa0,transparent:true,opacity:.8,side:THREE.DoubleSide}),p.x,.29,p.z,game.previewGroup);
    border.rotation.x=-Math.PI/2;border.rotation.z=Math.PI/4;
  }
}
function previewSummary(routes){
  return routes.map((r,i)=>{
    if(!r)return 'ABC'[i]+' → 无路';
    let exit=game.map.exits.findIndex(e=>key(...e)===key(...r[r.length-1]));
    return 'ABC'[i]+' → '+(game.map.exits.length===1?'中枢':exit===0?'X':'Y');
  }).join('  ·  ');
}
function previewCell(){if(!placing)return;let c=placing.cell||placing.hover;if(!c)return;let type=placing.type;clearGroup(game.previewGroup);$('#placementRoute').textContent='';let p=pos(c.x,c.z);let ring=mesh(type==='inter'?new THREE.RingGeometry(.12,TOWERS[type].range*unit,40,1,-Math.PI/2-1.15+placing.angle,2.3):new THREE.RingGeometry(.45,(TOWERS[type]?.range||1)*unit,40),new THREE.MeshBasicMaterial({color:0xa3ffe0,transparent:true,opacity:.12,side:THREE.DoubleSide}),p.x,.35,p.z,game.previewGroup);ring.rotation.x=-Math.PI/2;if(c.node&&['gate','fire','isolate'].includes(type)){if(game.blocked.has(c.k)||game.towers.some(t=>t.cell===c)){notify('该节点已有隔离设备');return}if((game.cool.get(c.k)||0)>game.time){notify('节点旁路冷却中 / '+Math.ceil(game.cool.get(c.k)-game.time)+' 秒');return}if(validBlock(c.k)){let b=new Set(game.blocked);b.add(c.k);let rs=routesFor(b);drawRoutes(game.previewGroup,rs,true);let changed=rs.map((r,i)=>JSON.stringify(r)!==JSON.stringify(game.routes[i])?'ABC'[i]:null).filter(Boolean).join(' / ');$('#placementRoute').textContent='白线 / '+previewSummary(rs)+' · 改道 '+(changed||'无');notify('白线预览 / '+previewSummary(rs)+' · 改道 '+(changed||'无'))}else notify('操作被拒 / '+blockProblem(c.k))}else if(type==='slow'&&c.road){let slow=new Map(game.slow);for(let tile of slowArea(c))slow.set(tile.k,game.time+15);previewSlowArea(c);let rs=routesFor(game.blocked,slow);drawRoutes(game.previewGroup,rs,true);let changed=rs.map((r,i)=>JSON.stringify(r)!==JSON.stringify(game.routes[i])?'ABC'[i]:null).filter(Boolean);$('#placementRoute').textContent='白线 / '+previewSummary(rs)+(changed.length?' · 改道 '+changed.join('、'):' · 路线不变');notify('金色地块 / 降级范围 · 白线 / '+previewSummary(rs)+(changed.length?' · 改道 '+changed.join('、'):' · 路线不变'))}}
function confirmPlace(){if(!placing?.cell){notify('请先选择位置');return}let {type,cell}=placing;if(type==='remove'){let t=placing.tower;if(!game.towers.includes(t)){cancelPlace();notify('设备已失效');return}removeTower(t,true);cancelPlace();renderUI();return}if(!TOWERS[type]&&(game.toolCooldown[type]||0)>game.time){notify('\u9053\u5177\u51b7\u5374\u4e2d');return}if(TOWERS[type]){if(createTower(type,cell)){cancelPlace();renderUI()}return}if(type==='isolate'){if(!cell.node||game.blocked.has(cell.k)||game.intel<3){notify('无法隔离此节点或情报不足');return}let problem=blockProblem(cell.k);if(problem){notify('操作被拒 / '+problem);return}let t=createTower('gate',cell,true);if(!t)return;game.intel-=3;t.temporary=game.time+18;markTemporaryIsolation(t);log('应急隔离器生效 / 18 秒')}if(type==='slow'){if(!cell.road||game.intel<2){notify('请选择链路，或检查情报');return}game.intel-=2;for(let c of slowArea(cell))game.slow.set(c.k,game.time+15);for(let e of game.enemies)if(e.type!=='fly'&&game.slow.has(occupiedTile(e)))e.revealed=true;refreshSlowVisual();updateRoutes();log('协议降级生效 / 附近链路减速并检测')}if(type==='restore'){let t=game.towers.find(t=>t.cell===cell);if(!t||game.cpu<30){notify('请选择设备，或检查算力');return}game.cpu-=30;let restored=Math.min(t.maxhp-t.hp,60);t.hp+=restored;towerFeedback(t,restored?'+'+Math.ceil(restored):'','#a6ffe0');t.hpbar.scale.x=t.hp/t.maxhp;t.encrypted=0;effect(t.group.position.clone().add(new THREE.Vector3(0,1.8,0)),t.group.position.clone().add(new THREE.Vector3(0,.5,0)),0x9df5d7);log('备份还原完成 / 耐久恢复，加密解除')}game.toolCooldown[type]=game.time+15;sfx(type);cancelPlace();renderUI()}
function pickCell(x,y){mouse.x=x/innerWidth*2-1;mouse.y=-(y/innerHeight)*2+1;raycaster.setFromCamera(mouse,camera);let hits=raycaster.intersectObjects(world.children,true);let h=hits.find(h=>h.object.userData.cell);return h?.object.userData.cell}
function pointerDown(e){if(mode!=='battle')return;if(e.button===1){dragCam={x:e.clientX,y:e.clientY,shift:e.shiftKey};e.preventDefault();return}if(e.button!==0)return;mouse.x=e.clientX/innerWidth*2-1;mouse.y=-(e.clientY/innerHeight)*2+1;raycaster.setFromCamera(mouse,camera);let hits=raycaster.intersectObjects(world.children,true);if(placing){let c=hits.find(h=>h.object.userData.cell)?.object.userData.cell;if(c)chooseCell(c)}else{let h=hits.find(h=>h.object.userData.tower||h.object.userData.enemy||h.object.userData.cell);selected=h&&(h.object.userData.tower||h.object.userData.enemy||h.object.userData.cell);renderInspect()}}
function pointerMove(e){if(dragCam){let dx=e.clientX-dragCam.x,dy=e.clientY-dragCam.y;dragCam.x=e.clientX;dragCam.y=e.clientY;if(dragCam.shift){let units=2*orbit.r*Math.tan(THREE.MathUtils.degToRad(camera.fov/2))/innerHeight,right=new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld,0),up=new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld,1);orbit.target.addScaledVector(right,-dx*units);orbit.target.addScaledVector(up,dy*units)}else{orbit.theta-=dx*.006;orbit.phi=Math.max(.25,Math.min(1.35,orbit.phi+dy*.006))}updateCamera()}else if(placing&&!placing.cell&&e.target===renderer.domElement){let c=pickCell(e.clientX,e.clientY);if(c&&c!==hoverCell){hoverCell=c;placing.hover=c;previewCell()}}}
function pointerUp(e){if(e.button===1)dragCam=null}function wheel(e){if(mode!=='battle')return;e.preventDefault();orbit.r=Math.max(9,Math.min(29,orbit.r+e.deltaY*.012));updateCamera()}function updateCamera(){let {theta,phi,r,target}=orbit;camera.position.set(target.x+r*Math.sin(phi)*Math.sin(theta),target.y+r*Math.cos(phi),target.z+r*Math.sin(phi)*Math.cos(theta));camera.lookAt(target)}function resize(){setUIScale();camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)}
function loop(){requestAnimationFrame(loop);let dt=Math.min(clock.getDelta(),.05);if(mode!=='battle')animateBackdrop(clock.elapsedTime);if(!exporting){if(demo&&game&&!game.paused)advanceDemo(dt*game.speed);update(dt)}renderer.render(scene,camera)}
function playDemo(i,exportMode=false){
  startGame(i,true);demo={id:i,time:0,steps:new Set(),duration:19};
  game.cpu=500;game.intel=25;game.wave=i===2?16:i===1?10:3;game.running=true;game.currentPlan=wavePlan(game.wave);game.spawn=[];game.spawnTime=0;
  for(let j=0;j<6;j++){
    let entry=j%game.map.entries.length,e=spawn(j%3===0?'flood':j%3===1?'worm':'trojan',entry);
    if(i===0&&entry===0)e.staging=1.5;
  }
  if(i===0){
    createTower('fire',cellAt(9,3),true);
    createTower('sandbox',cellAt(8,2),true);
  }
  if(i===1){
    createTower('gate',cellAt(...game.map.nodes[2]),true);
    createTower('fire',cellAt(9,6),true);
    createTower('fire',cellAt(1,2),true);
    createTower('repair',cellAt(0,2),true);
    placing={angle:Math.PI};createTower('inter',cellAt(2,2),true);placing=null;
    spawn('flood',1,[9,7]);
    for(let entry=0;entry<3;entry++)for(let j=0;j<2;j++)spawn(j?'trojan':'worm',entry,game.routes[entry][j+1]);
    game.spawn=[{time:6.4,type:'worm',entry:0},{time:7.5,type:'trojan',entry:0},{time:8.5,type:'flood',entry:0},{time:9.4,type:'worm',entry:0}];
  }
  if(i===2){
    createTower('repair',cellAt(8,5),true);
    let t=createTower('fire',cellAt(...game.map.nodes[2]),true);
    if(t){t.hp=110;t.hpbar.scale.x=t.hp/t.maxhp;t.encrypted=14;t.encryptRing.visible=true}
    placing={angle:Math.PI};createTower('inter',cellAt(2,4),true);placing=null;
    spawn('worm',1,[8,6]);spawn('flood',2,[9,5]);spawn('worm',0,[1,2]);
    let boss=spawn('boss',0);boss.phase=2;boss.hp=boss.maxhp*.29;boss.hpbar.scale.x=.29;boss.armor=.3;boss.revealed=true;boss.phaseRing.visible=true;boss.phaseRing.material=mats.red;boss.phaseGlow.visible=true;boss.bossTimer=25;
  }
  game.currentPlan={surge:i===1,perEntry:game.map.entries.map(()=>({count:0,types:new Set()}))};
  for(let e of game.enemies){let entry=game.currentPlan.perEntry[e.entry];entry.count++;entry.types.add(e.type)}
  for(let e of game.spawn){let entry=game.currentPlan.perEntry[e.entry];entry.count++;entry.types.add(e.type)}
  $('#subtitle').classList.remove('hidden');let cursor=$('#demoCursor');cursor.classList.remove('hidden','pressed');cursor.style.left='0px';cursor.style.top='0px';cursor.style.opacity='0';cursor.dataset.action='';
  $('#subtitle').textContent=['分段取舍 / 两侧防线正在交火','旁路直通 / 洪峰冲击汇聚节点','蛰影现身 / 深层防线承受攻击'][i];
  if(!exportMode)notify('实战演示开始 / 可从菜单退出');renderUI()
}
function demoStep(n,fn){if(demo.time+1e-7>=n&&!demo.steps.has(n)){demo.steps.add(n);fn()}}
function mostImpactfulLock(){let base=game.routes.map(r=>JSON.stringify(r)),best=null;for(let c of game.grid){if(!c.road||c.node||c.entry||c.exit||game.blocked.has(c.k)||!validBlock(c.k))continue;let b=new Set(game.blocked);b.add(c.k);let changed=routesFor(b).filter((r,i)=>JSON.stringify(r)!==base[i]).length;if(changed>0&&(!best||changed>best.changed))best={cell:c,changed}}return best?.cell||null}
function warningMarker(c){
  let p=pos(c.x,c.z),g=new THREE.Group();world.add(g);g.position.set(p.x,.32,p.z);
  let r=mesh(new THREE.TorusGeometry(.48,.035,8,20),mats.gold,0,0,0,g);r.rotation.x=Math.PI/2;
  for(let i=0;i<4;i++){let a=i*Math.PI/2,mark=box(.07,.28,.07,mats.gold,Math.cos(a)*.42,.16,Math.sin(a)*.42,g);mark.rotation.z=.2}
  let center=mesh(new THREE.OctahedronGeometry(.1),mats.gold,0,.53,0,g);g.userData.warningCore=center;
  return g
}
function lockCell(c,duration=8){if(!c||game.blocked.has(c.k)||!validBlock(c.k))return false;game.blocked.add(c.k);let p=pos(c.x,c.z),marker=new THREE.Group();world.add(marker);marker.position.set(p.x,.25,p.z);let disk=mesh(new THREE.TorusGeometry(.43,.07,6,12),mats.red,0,0,0,marker);disk.rotation.x=Math.PI/2;box(.65,.08,.08,mats.red,0,.06,0,marker);game.bossLocks.push({cell:c,marker,time:duration});routeTransition(c,0xff796e);updateRoutes();log('路由异常 / 链路暂时锁死');sfx('isolate');return true}
function advanceDemo(dt){
 if(!demo||!game)return;demo.time+=dt;let d=demo,i=d.id;
 if(d.warning?.userData.warningCore)d.warning.userData.warningCore.rotation.y=game.time*3;
 demoStep(1.4,()=>{if(i===0){beginPlace('gate');$('#subtitle').textContent='拖动网闸 / 选择西边界节点'}});
 demoStep(2.2,()=>{if(i===2){d.targetCell=mostImpactfulLock();if(d.targetCell)d.warning=warningMarker(d.targetCell);$('#subtitle').textContent='蛰影进入破坏阶段 / 运维环即将锁死'}});
 demoStep(3.2,()=>{if(i===0){chooseCell(cellAt(...game.map.nodes[0]));$('#subtitle').textContent='预览隔离 / 入口 A 将转向 DMZ 互联'}});
 demoStep(5,()=>{if(i===1){let t=game.towers.find(t=>t.type==='gate');if(t)removeTower(t,false);$('#subtitle').textContent='洪泛团冲毁网闸 / B、C 重新接入原数据中心'}});
 demoStep(5.6,()=>{if(i===0){d.confirmPoint=demoElementPoint('#confirmPlace');confirmPlace();$('#subtitle').textContent='隔离生效 / 办公网段威胁沿旁路掉头'}});
 demoStep(5.8,()=>{if(i===2){if(d.warning){world.remove(d.warning);disposeTree(d.warning);d.warning=null}let c=d.targetCell;if(c&&validBlock(c.k)){lockCell(c,12);$('#subtitle').textContent='运维环锁死 / 各入口重新收敛'}else $('#subtitle').textContent='路况已变化 / 本次封锁预警取消'}});
 demoStep(6.5,()=>{if(i===1){beginPlace('slow');$('#subtitle').textContent='选择协议降级 / 保护入口 A 防线'}});
 demoStep(8,()=>{if(i===1){chooseCell(cellAt(1,2));$('#subtitle').textContent='预览降级范围 / 旧协议减速并暴露威胁'}});
 demoStep(8.4,()=>{if(i===2){selected=game.towers.find(t=>t.type==='repair');renderInspect();$('#subtitle').textContent='选中修复进程 / 准备冗余切换'}});
 demoStep(10.3,()=>{if(i===1){d.confirmPoint=demoElementPoint('#confirmPlace');confirmPlace();$('#subtitle').textContent='协议降级生效 / 减缓 A 路进攻'}if(i===2){d.skillPoint=demoElementPoint('#inspectSkill');if(selected)skill();$('#subtitle').textContent='冗余切换 / 防线解除加密并获得护盾'}});
 demoStep(13,()=>{$('#subtitle').textContent=['旁路交汇 / 守方火力继续压制威胁','旁路直通后 / 防线争取重整时间','防线重启 / 修复与拦截持续进行'][i]});
 demoStep(16,()=>{$('#subtitle').textContent='战况仍在变化 / 守护进程继续监控'});
 demoVisual();if(d.time>=d.duration&&!exporting){demo=null;$('#subtitle').classList.add('hidden');$('#demoCursor').classList.add('hidden');notify('演示结束 / 可以继续操作')}
}
window.videoExport={runs:['demo-1','demo-2','demo-3'],begin:async function(runId,options={}){let i=this.runs.indexOf(runId);if(i<0)throw Error('Unknown run');exporting=true;document.body.classList.add('exporting');this.fps=options.fps||60;playDemo(i,true);game.paused=false;this.t=0;demoVisual();document.body.getBoundingClientRect();renderer.render(scene,camera);renderer.getContext().flush();return {frames:Math.ceil(demo.duration*this.fps)}},frame:async function(i){let target=i/this.fps;while(this.t+1e-8<target){let dt=Math.min(1/60,target-this.t);advanceDemo(dt);update(dt);this.t+=dt}document.body.getBoundingClientRect();renderer.render(scene,camera);renderer.getContext().flush()},end:function(){exporting=false;document.body.classList.remove('exporting');demo=null;$('#subtitle').classList.add('hidden');$('#demoCursor').classList.add('hidden');if(game)renderUI()}};
setupUI();init();
function decorateMap(index){
  const g=new THREE.Group();world.add(g);decorateInfrastructure(index,g);
  if(index===0){for(let i=0;i<6;i++){let x=-5.5+i*2.2,z=-5.7,h=.5+(i%3)*.3;box(.65,h,.45,mats.base,x,h/2-.2,z,g);for(let j=0;j<3;j++)box(.4,.035,.02,mats.green,x,j*.13+.1,z+.23,g)}}
  if(index===1){for(let i=0;i<16;i++){let x=-8+i*1.05;box(.6,.06,.15,mats.gold,x,-.25,-5.8,g);if(i%3===0){let tor=mesh(new THREE.TorusGeometry(.4,.025,6,12),mats.green,x,-.05,-5.8,g);tor.rotation.y=Math.PI/2}}for(let z of [-4,4])for(let x of [-7,7]){box(.8,.85,.8,mats.base,x,.1,z,g);for(let j=0;j<4;j++)box(.52,.04,.02,mats.green,x,-.15+j*.15,z+.41,g)}}
  if(index===2){for(let x of [-7,7])for(let z of [-4,0,4]){cyl(.42,.48,.25,mats.edge,x,-.1,z,g,12);cyl(.12,.14,.9,mats.gold,x,.45,z,g,8);let ring=mesh(new THREE.TorusGeometry(.28,.025,6,12),mats.gold,x,.8,z,g);ring.rotation.x=Math.PI/2}}
}
function bossBlock(e){if(e.warning){world.remove(e.warning);disposeTree(e.warning);e.warning=null}let c=e.warnCell;e.warnCell=null;if(!c||game.blocked.has(c.k)||!validBlock(c.k))return false;return lockCell(c)}
function ambientNote(index,time){ambientMusic(index,time)}
function demoElementPoint(selector){let r=document.querySelector(selector)?.getBoundingClientRect();return r?{x:r.left+r.width/2,y:r.top+r.height/2}:{x:innerWidth/2,y:innerHeight/2}}
function demoVisual(){
 if(!demo||!game)return;let time=demo.time+1e-7,id=demo.id;
 let focus=id===0?[5,3.5]:id===1?game.map.nodes[2]:demo.targetCell?[demo.targetCell.x,demo.targetCell.z]:game.map.nodes[1];
 let focusPos=pos(...focus),zoom=time<1.5?0:time<3.5?(time-1.5)/2:time<14?1:Math.max(0,1-(time-14)/2),blend=(v,a,b)=>Math.max(0,Math.min(1,(v-a)/(b-a)));
 if(id===0&&time>5.6){let e=game.enemies.find(e=>e.entry===0);if(e)focusPos.lerp(e.group.position,blend(time,5.6,8))}
 if(id===1&&time>5)focusPos.lerp(pos(1,2),blend(time,5,7.5));
 if(id===2&&time>6.5){let repair=game.towers.find(t=>t.type==='repair');if(repair)focusPos.lerp(repair.group.position,blend(time,6.5,8.5));let boss=game.enemies.find(e=>e.type==='boss');if(boss&&time>13)focusPos.lerp(boss.group.position,blend(time,13,15))}
 orbit.r=defaultRadius()-(id===0?4:5)*zoom;orbit.target.set(focusPos.x*.45*zoom,0,focusPos.z*.45*zoom);updateCamera();camera.updateMatrixWorld();
 const cursor=$('#demoCursor'),mix=(a,b,t)=>({x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t}),ease=(t,a,b)=>{let x=blend(t,a,b);return x*x*(3-2*x)};
 let point,action='',pressed=false,show=false;
 if(id===0){
   let card=demoElementPoint('[data-type="gate"]'),tile=screenPoint(pos(...game.map.nodes[0])),confirm=demo.confirmPoint||demoElementPoint('#confirmPlace');
   if(time>=.7&&time<6.2){show=true;if(time<1.4){point=mix({x:card.x-70,y:card.y-65},card,ease(time,.7,1.3));action='选择网闸'}else if(time<3.2){point=mix(card,tile,ease(time,1.4,3.2));action='按住拖动';pressed=true}else if(time<4.3){point=tile;action='查看预览'}else{point=mix(tile,confirm,ease(time,4.3,5.4));action='确认隔离';pressed=time>=5.5&&time<5.8}}
 }else if(id===1){
   let card=demoElementPoint('[data-type="slow"]'),tile=screenPoint(pos(1,2)),confirm=demo.confirmPoint||demoElementPoint('#confirmPlace');
   if(time>=5.8&&time<10.9){show=true;if(time<6.5){point=mix({x:card.x-65,y:card.y-55},card,ease(time,5.8,6.4));action='选择道具'}else if(time<8){point=mix(card,tile,ease(time,6.5,8));action='选择链路';pressed=time<6.7}else if(time<9){point=tile;action='查看范围'}else{point=mix(tile,confirm,ease(time,9,10.1));action='确认降级';pressed=time>=10.2&&time<10.5}}
 }else{
   let repair=game.towers.find(t=>t.type==='repair'),target=screenPoint(repair?repair.group.position:focusPos),button=demo.skillPoint||demoElementPoint('#inspectSkill');
   if(time>=7.3&&time<10.9){show=true;if(time<8.4){point=mix({x:target.x+65,y:target.y+65},target,ease(time,7.3,8.3));action='选中设备';pressed=time>=8.3}else if(time<8.9){point=target;action='查看状态'}else{point=mix(target,button,ease(time,8.9,10.1));action='释放技能';pressed=time>=10.2&&time<10.5}}
 }
 let rect=$('#battle').getBoundingClientRect(),scale=parseFloat(getComputedStyle($('#battle')).zoom)||1;
 if(point){cursor.style.left=((point.x-rect.left)/scale)+'px';cursor.style.top=((point.y-rect.top)/scale)+'px'}
 cursor.style.opacity=show?'1':'0';cursor.dataset.action=action;cursor.classList.toggle('pressed',pressed);
}
function screenPoint(v){let p=v.clone();p.y+=.4;p.project(camera);return {x:(p.x+1)*innerWidth/2,y:(1-p.y)*innerHeight/2}}
function showDeployable(type){let group=game.highlightGroup;clearGroup(group);for(let c of game.grid){let allowed=type==='gate'||type==='isolate'?c.node&&!game.blocked.has(c.k):type==='honey'?c.road&&!c.node&&!c.entry&&!c.exit:type==='fire'?c.road&&!c.entry&&!c.exit:['inter','sandbox','repair'].includes(type)?!c.road&&!c.obstacle:type==='slow'?c.road:type==='restore'?game.towers.some(t=>t.cell===c):false;if(!allowed||game.towers.some(t=>t.cell===c)&&type!=='restore'||c.node&&['fire','gate','isolate'].includes(type)&&(game.cool.get(c.k)||0)>game.time)continue;let p=pos(c.x,c.z),r=mesh(new THREE.RingGeometry(.42,.46,4),new THREE.MeshBasicMaterial({color:0x9bf4d1,transparent:true,opacity:.6,side:THREE.DoubleSide}),p.x,.36,p.z,group);r.rotation.x=-Math.PI/2;r.rotation.z=Math.PI/4}}
function bossWarning(e){
  // Prefer the route the boss is actually approaching, while preserving connectivity.
  const valid=c=>c&&c.road&&!c.node&&!c.entry&&!c.exit&&!game.blocked.has(c.k)&&!game.towers.some(t=>t.cell===c)&&validBlock(c.k);
  let path=route(e.to||e.cell)||[],ahead=path.slice(2).map(([x,z])=>cellAt(x,z)).filter(valid);
  if(!ahead.length)ahead=path.slice(1,2).map(([x,z])=>cellAt(x,z)).filter(valid);
  if(!ahead.length){
    // When the last branch is too narrow, choose the nearest safe alternative.
    ahead=game.grid.filter(valid).sort((a,b)=>dist(pos(a.x,a.z),e.group.position)-dist(pos(b.x,b.z),e.group.position));
  }
  if(!ahead.length)return;
  let c=ahead[0];e.warnCell=c;e.warning=warningMarker(c);
  sfx('warning');notify('封锁预警 / '+c.x+':'+c.z)
}

